import type { Blueprint, ExamConfig } from '@/lib/assessment/types';

/**
 * The exam details an exam hub shows from the configurations (summary,
 * version, cycle, section names, practice formats), in the language of a
 * translated hub (src/lib/exams/hub-content.ts, HUB_TRANSLATIONS). The
 * configurations stay English, the source of truth; these are their
 * translations, and tests/unit/hub-translations.test.ts fails when a
 * configuration gains a section or a format with no translation here.
 *
 * Format labels and descriptions are generated by the same sentence
 * patterns sectionedBlueprints uses (src/lib/exams/sectioned-blueprints.ts),
 * so their numbers always come from the configuration.
 */

export interface ExamDetailsTranslation {
  name: string;
  /** The official scale's label, when the configuration has one. */
  scaleLabel?: string;
  summary: string;
  versionLabel: string;
  admissionsCycle: string;
  sections: Readonly<Record<string, string>>;
}

