const TRANSLATIONS: Readonly<Record<string, Readonly<Record<string, ExamDetailsTranslation>>>> = { it: IT };

/** The exam details of `examKey` in `locale`, or undefined when there is no translation. */
export function examDetailsTranslation(examKey: string, locale: string): ExamDetailsTranslation | undefined {
  return TRANSLATIONS[locale]?.[examKey];
}

/** Every translated exam, for tests: [locale, examKey]. */
export function listExamDetailsTranslations(): Array<[string, string]> {
  return Object.entries(TRANSLATIONS).flatMap(([locale, byExam]) => Object.keys(byExam).map((key): [string, string] => [locale, key]));
}

/**
 * A format's label and description in Italian, from the English sentence
 * sectionedBlueprints wrote, or undefined when the sentence is not one of its
 * patterns (the test then fails rather than the page showing English).
 */
export function blueprintTextIt(
  config: Pick<ExamConfig, 'examKey'>,
  blueprint: Pick<Blueprint, 'label' | 'description'>,
): { label: string; description: string } | undefined {
  const details = IT[config.examKey];
  if (!details) return undefined;
  // Section names appear in the English sentences as the config writes them; their keys are the same words, hyphenated.
  return blueprintSentences(blueprint, (name) => details.sections[name.toLowerCase().replace(/\s+/g, '-')]);
}

function blueprintSentences(
  blueprint: Pick<Blueprint, 'label' | 'description'>,
  section: (englishName: string) => string | undefined,
): { label: string; description: string } | undefined {
  const { label, description } = blueprint;

  let m = /^Full simulation - (\S+)$/.exec(label);
  if (m) {
    const d = /^The complete published structure: (\d+) questions in (\d+) consecutive sections \((.+)\), (\d+) minutes in all\./.exec(description);
    if (!d) return undefined;
    const parts = d[3].split('; ').map((part) => {
      const p = /^(.+) (\d+) in (\d+) min$/.exec(part);
      const name = p && section(p[1]);
      return p && name ? `${name} ${p[2]} in ${p[3]} min` : undefined;
    });
    if (parts.some((part) => !part)) return undefined;
    return {
      label: `Simulazione completa - ${m[1]}`,
      description: `La struttura completa pubblicata: ${d[1]} domande in ${d[2]} sezioni consecutive (${parts.join('; ')}), ${d[4]} minuti in tutto. Ogni sezione ha il proprio tempo e, una volta chiusa, non si può riaprire. Se esci il tempo continua a scorrere, come il giorno del test.`,
    };
  }

  m = /^(\S+) diagnostic skill check$/.exec(label);
  if (m) {
    const d = /^A short (\d+)-question check across every (\S+) section,/.exec(description);
    if (!d) return undefined;
    return {
      label: `Verifica diagnostica delle competenze - ${m[1]}`,
      description: `Una breve verifica di ${d[1]} domande su tutte le sezioni del ${d[2]}, con tempi larghi, perché il risultato rifletta ciò che sai più che la velocità con cui lavori.`,
    };
  }

  m = /^(\S+) practice set$/.exec(label);
  if (m) {
    const d = /^An untimed (\d+)-question set from anywhere in the (\S+) syllabus\./.exec(description);
    if (!d) return undefined;
    return {
      label: `Esercitazione - ${m[1]}`,
      description: `Una serie di ${d[1]} domande senza limiti di tempo da tutto il sillabo del ${d[2]}. Prima di iniziare scegli sezione, argomento, difficoltà e numero di domande.`,
    };
  }

  m = /^(.+): timed section \((\d+) questions, (\d+) minutes\)$/.exec(label);
  if (m) {
    const name = section(m[1]);
    const d = /^One (\S+) section at its published length and time: (\d+) questions in (\d+) minutes, with the \S+ penalty for wrong answers\.$/.exec(description);
    if (!name || !d) return undefined;
    return {
      label: `${name}: sezione a tempo (${m[2]} domande, ${m[3]} minuti)`,
      description: `Una sezione del ${d[1]} con il numero di domande e il tempo pubblicati: ${d[2]} domande in ${d[3]} minuti, con la penalizzazione del ${d[1]} per le risposte errate.`,
    };
  }

  return undefined;
}
